@Component("aPIClient-handler")
@ProcessingGroup("aPIClient-processing-group")
public class APIClientEventHandler {
	
	// core constructor
	APIClientEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAPIClientEvent
     */
    @EventHandler
    public void handle( CreateAPIClientEvent event) {
        entityManager.persist(new APIClient(event.getAPIClientId(), event.getName(), event.getClientId(), event.getRedirectUri(), event.getConsents(), event.getClientType()));
    }

    /*
     * @param	event UpdateAPIClientEvent
     */
    @EventHandler
    public APIClient handle( UpdateAPIClientEvent event) {
    	entityManager.merge(new APIClient(event.getAPIClientId(), event.getName(), event.getClientId(), event.getRedirectUri(), event.getConsents(), event.getClientType()));
    }
    
    /*
     * @param	event DeleteAPIClientEvent
     */
    @EventHandler
    public void on( DeleteAPIClientEvent event) {
    	APIClient entity = new APIClient();
   
    	// ------------------------------------------
    	// apply the APIClientId
    	// ------------------------------------------
    	entity.setAPIClientId( event.getAPIClientId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final APIClientRepository aPIClientEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(APIClientEventHandler.class.getName());

}
